// Unified course data API.
// Word data files are named {series}-{unit}.json (generated by scripts/convert.py)
// and lazy-loaded on demand — each becomes its own chunk, kept out of the main
// bundle. Use getUnit / getLesson / allWords throughout the app — never import
// the JSON directly. All data accessors are async (they may trigger a fetch).

import { COURSE_REGISTRY } from "./courses.js";
import meta from "./meta.json"; // { "hsk-1": { lessonCount, wordCount, idPrefix }, ... }

// Lazy per-unit loaders — Vite turns each match into its own dynamic chunk.
// Pattern requires a dash, so meta.json / pinyin.json are excluded.
const loaders = import.meta.glob("./*-*.json");

function key(seriesId, unitId) {
  return `${seriesId}-${unitId}`;
}

// Series + per-unit metadata (lesson/word counts, id prefix, availability),
// all from meta.json — no word data loaded. Drives HomeView's course grid and
// progress rings, plus Account/Admin totals.
export const courseRegistry = COURSE_REGISTRY.map((series) => ({
  ...series,
  units: series.units.map((unit) => {
    const m = meta[key(series.id, unit.id)];
    return {
      ...unit,
      available: unit.available && !!m,
      lessonCount: m ? m.lessonCount : 0,
      wordCount: m ? m.wordCount : 0,
      idPrefix: m ? m.idPrefix : null,
    };
  }),
}));

// Load (and cache) one unit's dataset. Returns null for unknown units.
const _unitCache = new Map(); // key → Promise<dataset|null>
export function loadUnit(seriesId, unitId) {
  const k = key(seriesId, unitId);
  if (_unitCache.has(k)) return _unitCache.get(k);
  const loader = loaders[`./${k}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _unitCache.set(k, p);
  return p;
}

// Async accessor aliases (all return Promises).
export const getUnit = loadUnit;

export async function getLesson(seriesId, unitId, lessonNum) {
  const ds = await loadUnit(seriesId, unitId);
  if (!ds) return null;
  return ds.lessons.find((l) => l.num === Number(lessonNum)) || null;
}

export async function allWords(seriesId, unitId) {
  const ds = await loadUnit(seriesId, unitId);
  if (!ds) return [];
  return ds.lessons.flatMap((l) => l.words);
}

// Flat index of every word across all courses, each tagged with its source
// (series / unit / lesson). Loads all units on demand, then caches — used only
// by 我的词 and global search, both lazy routes.
let _flatIndex = null;
async function buildFlatIndex() {
  const out = [];
  for (const series of COURSE_REGISTRY) {
    for (const unit of series.units) {
      const ds = await loadUnit(series.id, unit.id);
      if (!ds) continue;
      for (const lesson of ds.lessons) {
        for (const word of lesson.words) {
          out.push({
            word,
            series: series.id,
            seriesName: series.name,
            unit: unit.id,
            unitLabel: unit.label,
            lessonNum: lesson.num,
            lessonTitle: lesson.title,
          });
        }
      }
    }
  }
  return out;
}

export async function everyWord() {
  if (!_flatIndex) _flatIndex = await buildFlatIndex();
  return _flatIndex;
}

// Strip pinyin tone marks so "qishi" matches "qǐshì" (and lowercases).
function normalize(s) {
  return (s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

// Also drop whitespace — pinyin in the data is inconsistently spaced
// ("nǐ hǎo" vs "nǐhǎo"), so match space-insensitively.
function normalizePinyin(s) {
  return normalize(s).replace(/\s+/g, "");
}

// Does a word match a query? Matches hanzi (raw), pinyin (tone- and
// space-insensitive), or English meaning. Empty query matches everything.
// Shared by global search and the in-lesson search box. Pure/sync.
export function matchWord(word, query) {
  const raw = (query || "").trim();
  if (!raw) return true;
  return (
    word.hanzi.includes(raw) ||
    normalizePinyin(word.pinyin).includes(normalizePinyin(raw)) ||
    normalize(word.meaning).includes(normalize(raw))
  );
}

// Global cross-course search over hanzi / pinyin / English meaning.
// Returns { total, results } where results is capped at `limit` entries.
export async function searchAll(query, limit = 60) {
  const raw = query.trim();
  if (!raw) return { total: 0, results: [] };
  const index = await everyWord();
  const matches = index.filter((e) => matchWord(e.word, raw));
  return { total: matches.length, results: matches.slice(0, limit) };
}
